import{_ as s,o as t,c as e,ag as c}from"./chunks/framework.D5hoimZQ.js";const y=JSON.parse('{"title":"科学日报 · 2026-11-05（物理 · 硬 X 射线阿秒计量：在时域直接量出 170 as 脉冲）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/physics/science-daily-2026-11-05-physics.md","filePath":"topics/physics/science-daily-2026-11-05-physics.md"}'),i={name:"topics/physics/science-daily-2026-11-05-physics.md"};function n(r,o,d,a,l,g){return t(),e("div",null,[...o[0]||(o[0]=[c('<h1 id="科学日报-·-2026-11-05-物理-·-硬-x-射线阿秒计量-在时域直接量出-170-as-脉冲" tabindex="-1">科学日报 · 2026-11-05（物理 · 硬 X 射线阿秒计量：在时域直接量出 170 as 脉冲） <a class="header-anchor" href="#科学日报-·-2026-11-05-物理-·-硬-x-射线阿秒计量-在时域直接量出-170-as-脉冲" aria-label="Permalink to &quot;科学日报 · 2026-11-05（物理 · 硬 X 射线阿秒计量：在时域直接量出 170 as 脉冲）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> — 第55期 ｜ 科学板块（物理向 1 篇） 落盘说明：文件名带 <code>-physics</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-11-05-物理-·-1-1-先解决「怎么量脉冲」-才能做阿秒硬-x-射线实验" tabindex="-1">科学日报 2026-11-05（物理 · 1/1）：先解决「怎么量脉冲」，才能做阿秒硬 X 射线实验 <a class="header-anchor" href="#科学日报-2026-11-05-物理-·-1-1-先解决「怎么量脉冲」-才能做阿秒硬-x-射线实验" aria-label="Permalink to &quot;科学日报 2026-11-05（物理 · 1/1）：先解决「怎么量脉冲」，才能做阿秒硬 X 射线实验&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-11-05.md</code> ｜ DOI: 10.1038/s41586-026-11245-5 ｜ Nature (2026)</p></blockquote><ul><li>问题：<strong>亚埃空间分辨 + 阿秒时间分辨</strong>可直接观测<strong>物质中电子运动</strong>；自由电子激光产生的<strong>阿秒硬 X 射线脉冲</strong>具备这种时空灵敏度，但一直<strong>缺乏精确的脉冲计量与控制</strong>——无法可靠刻画脉冲本身，就无法做定量时间分辨实验。</li><li>方法：基于<strong>宽带 X 射线分束—延迟线（split-delay line）</strong> 建立<strong>阿秒硬 X 射线脉冲计量</strong>：用<strong>场关联（field-correlation）测量</strong>做时域刻画，用<strong>非顺序双光子吸收（non-sequential two-photon absorption）<strong>作</strong>非线性探针</strong>做<strong>强度自相关</strong>。</li><li>结果（实测）： <ul><li><strong>场关联测量</strong>首次在<strong>时域</strong>刻画脉冲的<strong>相干时间</strong>，并证明脉冲对之间的<strong>阿秒同步</strong>；</li><li>强度自相关<strong>在时域直接</strong>给出平均脉冲宽度 <strong>170 as</strong>；</li><li>这些工具使<strong>系统的阿秒时间分辨实验</strong>成为可能：<strong>X 射线泵浦—X 射线探测光谱与衍射</strong>，通向<strong>前所未有的时空分辨率</strong>下探测电子现象。</li></ul></li><li>洞察（对本库 <code>physics</code> × <code>materials</code>）： <ol><li><strong>「先造尺子（计量），再造实验』」</strong>——阿秒硬 X 射线源的瓶颈不在『产生脉冲』而在『<strong>量准脉冲</strong>』；作者把攻关点放在<strong>计量与控制</strong>上，一通百通；判据：<strong>当某类实验长期做不出定量结果时，先问『是不是缺一把能测准源本身的尺子』</strong>（呼应母题「<strong>改路径优于加力度</strong>」和 <code>topics/physics/science-daily-2026-11-04-physics.md</code> 的「<strong>外部信号 &gt; 自评分</strong>」——用<strong>独立的关联测量</strong>给脉冲定标）。</li><li><strong>「用非线性过程当探针，把不可及的时间尺度搬到可测量」</strong>——<strong>非顺序双光子吸收</strong>把<strong>阿秒时长</strong>转成<strong>可测的自相关信号</strong>；判据：<strong>要测比探测带宽更快的量时，找把它映成慢信号的非线性/关联过程</strong>。</li><li><strong>与库内呼应</strong>：与 <code>topics/physics/science-daily-2026-11-02-physics.md</code> 的 Floquet 工程、<code>topics/physics/science-daily-2026-10-26.md</code> 的亚周期中红外脉冲同属「<strong>用更好的测量/驱动手段打开新时间尺度</strong>」一脉。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/physics/index.md</code> ｜ <code>topics/physics/spectroscopy.md</code> ｜ 第55期 科学板块</p></blockquote><p>关键词：科学日报第55期、硬X射线阿秒计量、Hard X-ray attosecond metrology、亚埃空间分辨、阿秒时间分辨、自由电子激光XFEL、阿秒硬X射线脉冲、宽带X射线分束延迟线split-delay line、场关联测量、脉冲相干时间、阿秒同步、非顺序双光子吸收non-sequential two-photon absorption、强度自相关、170阿秒脉冲、X射线泵浦探测、X射线衍射、先造尺子再造实验、用独立关联测量给源定标、把快过程映成慢信号、外部信号大于自评分、改路径优于加力度</p><p>关联：<code>topics/physics/index.md</code>、<code>topics/physics/spectroscopy.md</code>、<code>topics/physics/science-daily-2026-11-04-physics.md</code>、<code>topics/physics/science-daily-2026-11-02-physics.md</code>、<code>topics/quantum-physics/index.md</code>、<code>ScienceDaily/daily/2026-11-05.md</code></p>',10)])])}const h=s(i,[["render",n]]);export{y as __pageData,h as default};
